-- The palette comes from lua/theme-data.lua (generated by chezmoi from
-- .chezmoidata/); lua/theme.lua applies it and keeps 'background' and
-- ColorScheme listeners (lualine) in sync.
return {
	"RRethy/base16-nvim",
	lazy = false,
	priority = 1000,
	config = function()
		local theme = require("theme")
		theme.apply(theme.data().current)
	end,
}
